void tick(const error_code& ec) {
  if (ec == asio::error::operation_aborted) return;   // cancellation
  auto batch = consumer.poll(max_batch);              // bounded batch
  for (auto& m : batch) handle(m);
  timer_.expires_after(idle_);
  timer_.async_wait(tick);
}

asio::awaitable<void> consume(Consumer& c) {
  asio::steady_timer t(co_await asio::this_coro::executor);
  for (;;) {
    auto [ec, batch] = co_await c.poll(max_batch, asio::as_tuple(asio::use_awaitable));
    if (ec) break;                                  // shutdown or fatal
    if (batch.empty()) { t.expires_after(idle); co_await t.async_wait(asio::use_awaitable); }
    else for (auto& m : batch) co_await handle(m);  // ack after handling
  }
}
